import {icon} from './icons.js';
import {appearance,themes,colors,setAppearance} from './appearance.js';
import {uid,today,monthOf,shiftMonth,daysInMonth,cents,sum,currencies,palette,freshData,demoData,accountBalance,netWorth,monthTransactions,summary,breakdown,categorySpent,limitsFor,advanceDate,validateTransaction,validateData,validDate,toCSV,parseCSV} from './model.js';
import {profiles,createProfile,unlock,saveVault,seal,unseal,deriveKey,newSalt,vaultKey,checkEnvelope} from './vault.js';

const $=s=>document.querySelector(s),app=$('#app'),modalRoot=$('#modal-root');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data=null,session=null,demo=false,page='overview',month=monthOf(),authMode='login',search='',filterType='',filterCategory='',filterAccount='',sort='newest',pageNum=1,saveBusy=false,undo=null,installPrompt=null,lastActivity=Date.now(),returnFocus=null,toastTimer,receiptDraft='',receiptBusy=false;
const themeOptions=()=>options(themes,appearance.theme),colorOptions=()=>options(colors,appearance.color);
const systemTheme=matchMedia('(prefers-color-scheme: dark)');
const navs=[['overview','grid','Overview'],['transactions','transactions','Transactions'],['budgets','budget','Budgets'],['accounts','wallet','Accounts'],['analytics','chart','Analytics'],['goals','goal','Savings goals'],['recurring','repeat','Recurring']];
const pageNames=Object.fromEntries([...navs,['settings','settings','Settings']].map(n=>[n[0],n[2]]));
function applyTheme(){
 document.documentElement.dataset.theme=appearance.theme==='system'?(systemTheme.matches?'dark':'light'):appearance.theme;
 document.documentElement.dataset.color=appearance.color;
 document.querySelector('meta[name="theme-color"]').content=getComputedStyle(document.documentElement).getPropertyValue('--bg').trim();
 document.querySelectorAll('[name="theme"]').forEach(el=>el.value=appearance.theme);
 document.querySelectorAll('[name="colorTheme"]').forEach(el=>el.value=appearance.color);
}
applyTheme();systemTheme.addEventListener('change',applyTheme);
const money=(n,compact=false)=>new Intl.NumberFormat(data?.currency==='INR'?'en-IN':'en-US',{style:'currency',currency:data?.currency||'INR',maximumFractionDigits:compact?0:2,minimumFractionDigits:compact?0:2}).format(n/100);
const fmtDate=(s,opts={day:'numeric',month:'short'})=>new Date(s+'T12:00:00').toLocaleDateString('en-GB',opts);
const monthName=m=>new Date(m+'-01T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'});
const pct=(a,b)=>b?Math.min(100,Math.max(0,a/b*100)):0;
const cat=id=>data.categories.find(c=>c.id===id)||{name:'Income',icon:'briefcase',color:'#739d79'};
const acct=id=>data.accounts.find(a=>a.id===id)?.name||'Unknown account';
const button=(label,action,ico='',cls='button secondary',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const tag=(s,cls='')=>`<span class="pill ${cls}">${esc(s)}</span>`;
const empty=(title,desc,action='',label='Add your first one',ico='leaf')=>`<div class="empty">${icon(ico)}<h3>${title}</h3><p>${desc}</p>${action?button(label,action,'plus','button primary'):''}</div>`;
const options=(rows,value)=>rows.map(([v,label])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(label)}</option>`).join('');
const accountOptions=id=>options(data.accounts.map(a=>[a.id,a.name]),id);
const categoryOptions=id=>options(data.categories.map(c=>[c.id,c.name]),id);
function toast(message,canUndo=false){clearTimeout(toastTimer);$('#toast').innerHTML=`${icon('check')}<span>${esc(message)}</span>${canUndo?'<button data-action="undo">Undo</button>':''}`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),canUndo?9000:5000);}
function haptic(){if(data?.preferences.haptics&&navigator.vibrate)navigator.vibrate(15);}
function showError(message){const el=$('#form-error');if(el){el.textContent=message;el.hidden=false;}else toast(message);}
function friendlyError(e){return e.name==='QuotaExceededError'?'Browser storage is full. Export a backup and remove large receipt images before trying again.':e.message||'Something went wrong. Please try again.';}
async function commit(mutator,message,allowUndo=false){if(saveBusy)throw Error('Please wait for the current save.');saveBusy=true;const before=structuredClone(data),next=structuredClone(data);try{mutator(next);validateData(next);if(!demo){if(navigator.locks)await navigator.locks.request('mayaxpense-'+session.id,()=>saveVault(session,next));else await saveVault(session,next);}data=next;if(allowUndo)undo=before;else undo=null;render();haptic();if(message)toast(message,allowUndo);return true;}finally{saveBusy=false;}}
function field(label,name,value='',type='text',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function select(label,name,opts){return `<label class="field">${label}<select name="${name}">${opts}</select></label>`;}
function formEnd(label='Save changes'){return `<p id="form-error" class="form-error" role="alert" hidden></p><div class="modal-footer">${button('Cancel','close','','button secondary')}<button class="button primary" type="submit">${icon('check')}${label}</button></div>`;}
function openModal(title,subtitle,body,cls=''){returnFocus=document.activeElement;modalRoot.innerHTML=`<dialog class="modal ${cls}" aria-labelledby="modal-title"><div class="modal-header"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div>${button('','close','close','icon-button','aria-label="Close dialog"')}</div>${body}</dialog>`;const dlg=modalRoot.firstElementChild;dlg.addEventListener('click',e=>{if(e.target===dlg){const r=dlg.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});dlg.addEventListener('cancel',e=>{e.preventDefault();closeModal();});dlg.showModal();}
function closeModal(){modalRoot.querySelector('dialog')?.close();modalRoot.innerHTML='';receiptDraft='';if(returnFocus?.isConnected)returnFocus.focus();}

function renderAuth(){let list=[];try{list=profiles();}catch{}const isNew=authMode==='signup';app.innerHTML=`<main class="auth-layout ${isNew?'auth-signup':'auth-login'}"><section class="auth-story"><a class="brand" href="/"> <img src="/icon.svg" alt="" width="38" height="38"><span>Maya<span class="brand-light">Xpense</span><span class="brand-dot">.</span></span></a><div class="story-content"><span class="eyebrow">A LITTLE CLARITY. A LOT MORE POSSIBILITY.</span><h1>Your money. <br>Your life.<br><em>In a good place.</em></h1><p>Spend with intention, save for the things you love, and feel a little more at home with your money.</p><div class="auth-visual"><div class="mini-receipt"><div class="flex-between"><span>${icon('leaf')} Your next chapter</span>${tag('Looking good','green')}</div><strong>More life.<br>Less money stress.</strong><div class="mini-bars">${[35,51,44,66,59,78,88,100].map((h,i)=>`<i style="height:${h}%;opacity:${.35+i*.09}"></i>`).join('')}</div><div class="flex-between muted small"><span>Small steps</span><span>Big possibilities ${icon('arrow')}</span></div></div><span class="floating-badge">${icon('shield')} Private by design</span></div></div><div class="story-foot">Made for your everyday. And your someday.</div></section><section class="auth-form-wrap"><div class="auth-theme">${button('Appearance','theme','settings','button secondary appearance-trigger','aria-haspopup="dialog"')}</div><div class="auth-form-inner"><h2>${isNew?'A fresh start for your money.':'Welcome back.'}</h2><p class="muted">${isNew?'Create your private MayaXpense profile.':'Your money, in a good place.'}</p><div class="segmented auth-tabs">${button('Sign in','auth-login','',!isNew?'selected':'',`aria-pressed="${!isNew}"`)}${button('Create profile','auth-signup','',isNew?'selected':'',`aria-pressed="${isNew}"`)}</div><form id="auth-form">${isNew?field('Your name','name','','text','required maxlength="40" autocomplete="given-name" placeholder="What should we call you?"'):''}${field('Username','username','','text','required minlength="3" maxlength="24" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="Your username" list="profile-names"')}<datalist id="profile-names">${list.map(p=>`<option value="${esc(p.username)}">`).join('')}</datalist><label class="field">Password<div class="password-field"><input name="password" type="password" required ${isNew?'minlength="10"':''} maxlength="200" autocomplete="${isNew?'new-password':'current-password'}" placeholder="${isNew?'At least 10 characters':'Enter your password'}">${button('','show-password','eye','icon-button','aria-label="Show password"')}</div></label>${isNew?`${field('Confirm password','confirm','','password','required minlength="10" maxlength="200" autocomplete="new-password" placeholder="One more time"')}<p class="small muted">Your password encrypts your data. Keep it safe — there is no password reset.</p>`:''}<p id="form-error" class="form-error" role="alert" hidden></p><button class="button primary auth-submit" type="submit">${isNew?'Create my space':'Unlock my space'} ${icon('arrow')}</button></form><div class="or"><span>just looking around?</span></div>${button('Explore the live demo','demo','arrow','button demo-button')}<p class="auth-local-note">${icon('lock')} Private on this device. No backend needed.</p><div class="auth-links">${button('Restore backup','restore','upload','text-button restore-link')}<details class="auth-details"><summary>About local profiles</summary><p>Profiles and encrypted records stay in this browser. There is no password reset or device sync. Export backups to keep your records safe or move them to another device.</p></details></div></div><div class="auth-footer">A little more clarity. A little more you.</div></section></main>`;}
function sidebar(){return `<aside class="sidebar"><a class="brand" href="#overview" data-nav="overview"><img src="/icon.svg" width="34" height="34" alt=""><span>Maya<span class="brand-light">Xpense</span><span class="brand-dot">.</span></span></a><div class="workspace-label"><span class="workspace-avatar">${esc(data.name[0]?.toUpperCase()||'M')}</span><div><strong>Personal space</strong><span>${demo?'Demo workspace':'Your private money journal'}</span></div>${icon('down')}</div><div class="nav-caption">YOUR WORKSPACE</div><nav aria-label="Main navigation">${navs.map(([key,ico,label])=>`<button data-nav="${key}" class="nav-item ${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${key==='recurring'&&data.recurring.filter(r=>r.next<=today()).length?'<span class="nav-count">'+data.recurring.filter(r=>r.next<=today()).length+'</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('leaf')}<strong>Little steps. Big dreams.</strong><p>Make space for the things<br>that matter to you.</p><button data-nav="goals">Find your next goal ${icon('arrow')}</button></div><button class="nav-item ${page==='settings'?'active':''}" data-nav="settings">${icon('settings')}<span>Settings & backup</span></button><div class="sidebar-profile"><span class="profile-avatar">${esc(data.name[0]?.toUpperCase()||'M')}</span><div><strong>${esc(data.name)}</strong><span>${demo?'Exploring MayaXpense':'Encrypted local profile'}</span></div>${button('','lock','logout','icon-button',`aria-label="${demo?'Exit demo':'Lock and sign out'}"`)}</div></div></aside>`;}
function render(){if(!data){renderAuth();return;}const m=summary(data,month);app.innerHTML=`<div class="app-shell">${sidebar()}<div class="main-shell"><header class="topbar"><div class="breadcrumbs"><span>Personal workspace</span>${icon('chevron')}<strong>${pageNames[page]}</strong></div><div class="topbar-actions">${demo?tag('Demo · changes stay in memory','demo-pill'):tag('Encrypted on this device','local-pill')}${button('','theme','settings','icon-button','aria-label="Choose appearance and color theme" aria-haspopup="dialog"')}${button('','alerts','bell','icon-button notification','aria-label="View budget and bill alerts"')}<span class="profile-avatar small-avatar" aria-label="${esc(data.name)}">${esc(data.name[0]?.toUpperCase()||'M')}</span></div></header><main id="main-content"><div class="page-heading"><div><div class="eyebrow">${page==='overview'?'YOUR MONEY, AT A GLANCE':page==='goals'?'A LITTLE CLOSER, EVERY DAY':page==='settings'?'MAKE YOURSELF AT HOME':'MAKE EVERY LITTLE BIT COUNT'}</div><h1>${page==='overview'?`A little clarity, ${esc(data.name)}<span class="wave"> ✳</span>`:pageNames[page]}</h1><p>${({overview:'Here’s where you stand. And where you can go.',transactions:'The little details that make up your bigger picture.',budgets:'A plan for your money. More room for your life.',accounts:'All your balances, in one good place.',analytics:'Get to know the story behind your spending.',goals:'Turn your someday into something you can see.',recurring:'Keep the regular things running smoothly.',settings:'Your preferences, privacy, and peace of mind.'})[page]}</p></div><div class="heading-actions">${['overview','transactions','budgets','analytics'].includes(page)?`<div class="month-control" aria-label="Reporting month">${button('','prev-month','chevron','icon-button previous','aria-label="Previous month"')}<label>${icon('calendar')}<span>${monthName(month)}</span><input type="month" aria-label="Reporting month" value="${month}" min="1900-01" max="2200-12"></label>${button('','next-month','chevron','icon-button','aria-label="Next month"')}</div>`:''}${page==='overview'||page==='transactions'?button('Add transaction','add-transaction','plus','button primary'):page==='budgets'?button('Create budget','add-budget','plus','button primary'):page==='accounts'?button('Add account','add-account','plus','button primary'):page==='goals'?button('New goal','add-goal','plus','button primary'):page==='recurring'?button('Add recurring','add-recurring','plus','button primary'):page==='analytics'?button('Export report','export-report','download'):''}</div></div><div id="page-content">${({overview:overview,transactions:transactions,budgets:budgets,accounts:accounts,analytics:analytics,goals:goals,recurring:recurring,settings:settings})[page](m)}</div><footer class="app-footer"><span>${icon('lock')} Your money story stays yours.</span><span>MayaXpense <span class="footer-dot">•</span> Make room for what matters.</span></footer></main></div><nav class="mobile-nav" aria-label="Mobile navigation">${[['overview','grid','Home'],['transactions','transactions','Activity'],['add','plus','Add'],['budgets','budget','Budgets'],['more','menu','More']].map(([key,ico,label])=>`<button ${key==='add'?'data-action="add-transaction"':key==='more'?'data-action="more"':`data-nav="${key}"`} class="${page===key?'active':''} ${key==='add'?'mobile-add':''}">${icon(ico)}<span>${label}</span></button>`).join('')}</nav></div>`;}

function statCard(label,amount,ico,foot,cls=''){return `<article class="stat-card ${cls}"><div class="flex-between"><span>${label}</span><span class="stat-icon">${icon(ico)}</span></div><strong>${money(amount,true)}</strong><p>${foot}</p></article>`;}
function overview(m){const lim=limitsFor(data,month),budgetTotal=lim.reduce((n,b)=>n+b.limit,0),budgetSpent=lim.reduce((n,b)=>n+categorySpent(data,month,b.category),0),left=budgetTotal-budgetSpent;const past=summary(data,shiftMonth(month,-1));const delta=past.expense?Math.round((m.expense-past.expense)/past.expense*100):null;const elapsed=month===monthOf()?Number(today().slice(8)):daysInMonth(month);const remaining=month===monthOf()?daysInMonth(month)-elapsed+1:daysInMonth(month);return `<section class="overview-hero"><div><span class="hero-label">${icon('leaf')} A little intention goes a long way</span><h2>Make room for<br><em>what matters.</em></h2><p>Your next adventure. A quieter mind. That thing you love.<br>It all starts with knowing your money.</p>${button('Plan this month','goto-budgets','arrow','button hero-button')}</div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="art-sprout"><div class="stem"></div><div class="art-leaf leaf-one"></div><div class="art-leaf leaf-two"></div><div class="art-leaf leaf-three"></div><div class="art-leaf leaf-four"></div><div class="plant-base"></div></div><span class="art-spark spark-one">✳</span><span class="art-spark spark-two">✧</span><div class="art-tag">${icon('chart')} Growing, at your own pace.</div></div></section><section class="stats-grid">${statCard('Total balance',netWorth(data),'wallet',`${data.accounts.length} accounts <span class="muted">· Balance today</span>`,'balance-card')}${statCard('Monthly income',m.income,'income',`${tag('Money in','green')} <span>this month</span>`)}${statCard('Monthly expenses',m.expense,'arrow',delta===null?'Your spending this month':`${tag((delta>0?'+':'')+delta+'% vs last month',delta<=0?'green':'orange')}`)}${statCard('Budget remaining',left,'budget',budgetTotal?`${Math.round(pct(budgetSpent,budgetTotal))}% used <span class="muted">of ${money(budgetTotal,true)} planned</span>`:'Create a budget to get started')}</section><div class="dashboard-grid"><section class="panel cashflow-panel"><div class="panel-head"><div><h2>Money in, money out</h2><p>A little perspective on your cash flow</p></div><div class="legend"><span><i class="income-dot"></i>Income</span><span><i class="expense-dot"></i>Expenses</span></div></div>${cashflowChart()}<div class="chart-foot"><span>${icon('spark')} ${m.income>0?`You’ve kept ${Math.max(0,m.rate)}% of this month’s income.`:'Log income and expenses to see your money story.'}</span><button class="text-button" data-nav="analytics">See insights ${icon('arrow')}</button></div></section><section class="panel spending-panel"><div class="panel-head"><div><h2>Where it’s going</h2><p>Your spending, simply put</p></div>${button('','goto-analytics','arrow','icon-button','aria-label="View spending analytics"')}</div>${donut(month)}<div class="category-legend">${breakdown(data,month).slice(0,4).map(c=>`<div><span><i style="background:${c.color}"></i>${esc(c.name)}</span><strong>${money(c.amount,true)}</strong></div>`).join('')}</div></section><section class="panel recent-panel"><div class="panel-head"><div><h2>The latest little things</h2><p>Your recent transactions</p></div><button class="text-button" data-nav="transactions">View all ${icon('arrow')}</button></div>${transactionTable(monthTransactions(data,month).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5),true)}</section><section class="panel budget-preview"><div class="panel-head"><div><h2>A plan in progress</h2><p>Checking in on your budgets</p></div><button class="text-button" data-nav="budgets">View all ${icon('arrow')}</button></div>${lim.length?lim.slice(0,4).map(b=>budgetRow(b)).join(''):empty('Give your money a plan','Set a monthly limit for the things you spend on.','add-budget','Create a budget','budget')}<div class="soft-note">${icon('leaf')} ${budgetTotal?`${money(Math.max(0,left)/remaining,true)} per day left in your budgeted categories.`:'A good budget makes room for joy, too.'}</div></section><section class="panel goal-preview"><div class="panel-head"><div><h2>Your someday fund</h2><p>Small steps toward something good</p></div><button class="text-button" data-nav="goals">All goals ${icon('arrow')}</button></div><div class="mini-goals">${data.goals.length?data.goals.slice(0,3).map(g=>`<button class="mini-goal" data-action="fund-goal" data-id="${g.id}"><span class="category-icon" style="--cat:${g.color}">${icon(g.icon)}</span><strong>${esc(g.name)}</strong><span>${money(g.saved,true)} <span class="muted">of ${money(g.target,true)}</span></span><div class="progress"><i style="width:${pct(g.saved,g.target)}%;background:${g.color}"></i></div><small>${Math.round(pct(g.saved,g.target))}% of the way there</small></button>`).join(''):empty('What are you dreaming of?','Give your next big thing a little space.','add-goal','Create a savings goal','goal')}</div></section><section class="panel upcoming-preview"><div class="panel-head"><div><h2>Coming up</h2><p>Your regular commitments</p></div><button class="text-button" data-nav="recurring">View all ${icon('arrow')}</button></div>${data.recurring.length?data.recurring.slice().sort((a,b)=>a.next.localeCompare(b.next)).slice(0,3).map(r=>billRow(r)).join(''):empty('A clear calendar','Add bills and subscriptions so nothing sneaks up.','add-recurring','Add recurring','calendar')}</section></div>`;}

function cashflowChart(){
 const months=Array.from({length:6},(_,i)=>shiftMonth(month,i-5)),vals=months.map(m=>summary(data,m));
 const max=Math.max(...vals.flatMap(s=>[s.income,s.expense]),10000),ceiling=Math.ceil(max/4/10000)*4*10000;
 const description=months.map((m,i)=>monthName(m)+': income '+money(vals[i].income)+', expenses '+money(vals[i].expense)).join('; ');
 return `<div class="chart-scroll"><div class="cashflow-chart" role="img" aria-label="Monthly income and expenses for ${description}"><div class="chart-axis" aria-hidden="true">${Array.from({length:5},(_,i)=>`<span style="bottom:${i*25}%">${money(ceiling/4*i,true)}</span>`).join('')}</div><div class="chart-periods" aria-hidden="true">${months.map((m,i)=>`<div class="chart-period"><div class="chart-bars"><i class="chart-bar income-dot" style="height:${vals[i].income/ceiling*100}%" title="${monthName(m)} income: ${money(vals[i].income)}"></i><i class="chart-bar expense-dot" style="height:${vals[i].expense/ceiling*100}%" title="${monthName(m)} expenses: ${money(vals[i].expense)}"></i></div><span>${new Date(m+'-01T12:00:00').toLocaleDateString('en',{month:'short'})}</span></div>`).join('')}</div></div></div>`;
}

function donut(m){const groups=breakdown(data,m),total=sum(groups);let acc=0;const segments=groups.map(c=>{const start=acc;acc+=c.amount/total*100;return `${c.color} ${start}% ${acc}%`;}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:${total?'conic-gradient('+segments+')':'var(--border)'}" role="img" aria-label="Total spending ${money(total)}. ${groups.map(c=>c.name+' '+Math.round(c.amount/total*100)+'%').join(', ')}"><div><span>Total spent</span><strong>${money(total,true)}</strong><small>${monthName(m).split(' ')[0]}</small></div></div></div>`;}
function transactionTable(ts,mini=false){if(!ts.length)return empty('Your story starts here','Log a transaction and let the bigger picture come together.','add-transaction','Add a transaction','transactions');return `<div class="table-wrap"><table class="transaction-table"><thead><tr><th>Transaction</th>${!mini?'<th>Category</th>':''}<th>Date</th><th>Account</th><th class="align-right">Amount</th><th><span class="sr-only">Actions</span></th></tr></thead><tbody>${ts.map(t=>{const c=t.type==='expense'?cat(t.category):{icon:t.type==='transfer'?'transactions':'income',color:t.type==='transfer'?'#839cbf':'#739d79',name:t.type==='transfer'?'Transfer':'Income'};return `<tr><td><button class="transaction-title" data-action="edit-transaction" data-id="${t.id}"><span class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</span><span><strong>${esc(t.title)}</strong><small>${mini?esc(c.name):t.tags?.length?t.tags.map(esc).join(' · '):t.note?esc(t.note.slice(0,42)):'—'}${t.receipt?' · Receipt attached':''}${t.date>today()?' · Scheduled':''}</small></span></button></td>${!mini?`<td>${tag(c.name)}</td>`:''}<td class="muted nowrap">${fmtDate(t.date)}</td><td class="muted">${esc(acct(t.account))}${t.type==='transfer'?' → '+esc(acct(t.to)):''}</td><td class="align-right amount ${t.type==='income'?'positive':''}">${t.type==='income'?'+':t.type==='expense'?'−':''}${money(t.amount)}</td><td>${button('','edit-transaction','dots','icon-button',`data-id="${t.id}" aria-label="Edit ${esc(t.title)}"`)}</td></tr>`;}).join('')}</tbody></table></div>`;}
function filteredTransactions(){return data.transactions.filter(t=>monthOf(t.date)===month&&(!filterType||t.type===filterType)&&(!filterCategory||t.category===filterCategory)&&(!filterAccount||t.account===filterAccount||t.to===filterAccount)&&(!search||[t.title,t.note,...t.tags||[],cat(t.category).name,acct(t.account)].join(' ').toLowerCase().includes(search.toLowerCase()))).sort((a,b)=>sort==='largest'?b.amount-a.amount:sort==='oldest'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));}
function transactions(){const ts=filteredTransactions(),pages=Math.max(1,Math.ceil(ts.length/25));pageNum=Math.min(pageNum,pages);return `<div class="transaction-summary"><span>${tag(ts.length+' transactions')} <span class="muted">in ${monthName(month)}</span></span><div>${button('Import CSV','import-csv','upload')}${button('Export CSV','export-csv','download')}</div></div><section class="panel"><div class="filter-bar"><label class="search-field">${icon('search')}<input id="transaction-search" placeholder="Search descriptions, notes, tags…" aria-label="Search transactions" value="${esc(search)}"></label><select id="filter-type" aria-label="Filter by type">${options([['','All types'],['expense','Expenses'],['income','Income'],['transfer','Transfers']],filterType)}</select><select id="filter-category" aria-label="Filter by category">${options([['','All categories'],...data.categories.map(c=>[c.id,c.name])],filterCategory)}</select><select id="filter-account" aria-label="Filter by account">${options([['','All accounts'],...data.accounts.map(a=>[a.id,a.name])],filterAccount)}</select><select id="sort" aria-label="Sort transactions">${options([['newest','Newest first'],['oldest','Oldest first'],['largest','Largest first']],sort)}</select></div>${transactionTable(ts.slice((pageNum-1)*25,pageNum*25))}<div class="table-footer"><span>${ts.length?`Showing ${(pageNum-1)*25+1}–${Math.min(pageNum*25,ts.length)} of ${ts.length}`:'No transactions'} <span class="muted">· Includes scheduled entries</span></span><div>${button('Previous','prev-page','','button secondary small-button',pageNum===1?'disabled':'')}<span> ${pageNum} / ${pages} </span>${button('Next','next-page','','button secondary small-button',pageNum===pages?'disabled':'')}</div></div></section><div class="soft-note">${icon('info')} Transfers move money between your accounts and don’t count as income or expenses. Future entries affect balances when their date arrives.</div>`;}
function budgetRow(b,full=false){const c=cat(b.category),spent=categorySpent(data,month,b.category),ratio=spent/b.limit,remaining=b.limit-spent;return `<${full?'article':'div'} class="budget-row ${full?'panel budget-card':''}"><div class="flex-between"><div class="budget-name"><span class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</span><strong>${esc(c.name)}</strong></div>${full?button('','edit-budget','dots','icon-button',`data-id="${b.id}" aria-label="Edit ${esc(c.name)} budget"`):`<span class="small ${ratio>1?'negative':'muted'}">${Math.round(ratio*100)}%</span>`}</div><div class="budget-values"><strong>${money(spent,true)} <span class="muted">of ${money(b.limit,true)}</span></strong>${full?tag(ratio>1?'Over budget':ratio>=.8?'Getting close':'On track',ratio>=.8?'orange':'green'):''}</div><div class="progress"><i style="width:${pct(spent,b.limit)}%;background:${ratio>1?'var(--red)':c.color}"></i></div>${full?`<div class="flex-between small"><span class="${remaining<0?'negative':'muted'}">${money(Math.abs(remaining),true)} ${remaining<0?'over budget':'left to spend'}</span><span>${Math.round(ratio*100)}% used</span></div>`:''}</${full?'article':'div'}>`;}
function budgets(){const lim=limitsFor(data,month),total=lim.reduce((n,b)=>n+b.limit,0),spent=lim.reduce((n,b)=>n+categorySpent(data,month,b.category),0),all=summary(data,month).expense;return `<div class="summary-banner"><span class="banner-icon">${icon('budget')}</span><div><span class="muted small">YOUR MONTHLY PLAN</span><h2>${money(Math.max(0,total-spent),true)} <span>left in your budgets</span></h2><p>${money(spent,true)} spent of ${money(total,true)} planned ${spent>total?'· '+money(spent-total,true)+' over budget':''}</p></div>${button('Copy last month','copy-budgets','repeat')}</div><div class="budget-grid">${lim.length?lim.map(b=>budgetRow(b,true)).join(''):empty('Start with what matters','Pick a category, give it a limit, and make a little room for life.','add-budget','Create your first budget','budget')}<button class="dashed-card" data-action="add-budget">${icon('plus')}<strong>Make a little plan</strong><span>Add a category budget</span></button></div><div class="soft-note">${icon('info')} Budgets apply to ${monthName(month)} only. ${money(Math.max(0,all-spent),true)} spent outside budgeted categories. Use “Copy last month” to reuse your plan.</div>`;}
function accounts(){const net=netWorth(data),balances=data.accounts.map(a=>accountBalance(data,a.id));return `<div class="summary-banner"><span class="banner-icon">${icon('wallet')}</span><div><span class="muted small">THE BIGGER PICTURE · TODAY</span><h2>${money(net,true)} <span>net balance</span></h2><p>${money(balances.filter(n=>n>0).reduce((a,b)=>a+b,0),true)} in assets · ${money(-balances.filter(n=>n<0).reduce((a,b)=>a+b,0),true)} in liabilities</p></div>${button('Move money','transfer','transactions')}</div><div class="account-grid">${data.accounts.map(a=>`<article class="account-card" style="--account:${a.color}"><div class="flex-between"><span class="account-card-icon">${icon(a.type==='cash'?'wallet':a.type==='credit'?'card':a.type==='investment'?'chart':'home')}</span>${button('','edit-account','dots','icon-button',`data-id="${a.id}" aria-label="Edit ${esc(a.name)}"`)}</div><span class="account-type">${esc(a.type)} account</span><h2>${esc(a.name)}</h2><strong class="account-balance">${money(accountBalance(data,a.id))}</strong><div class="account-card-foot"><span>${data.transactions.filter(t=>t.account===a.id||t.to===a.id).length} entries</span><span>Manually tracked ${icon('check')}</span></div></article>`).join('')}<button class="dashed-card" data-action="add-account">${icon('plus')}<strong>One more piece of the picture</strong><span>Add a bank, cash, credit, or investment account</span></button></div><div class="soft-note">${icon('info')} Balances = opening balance + recorded activity through today. Enter credit card debt as a negative opening balance. All accounts use ${data.currency}; there is no automatic bank sync or currency conversion.</div>`;}
function analytics(m){const groups=breakdown(data,month),ts=monthTransactions(data,month).filter(t=>t.type==='expense'),avg=ts.length?m.expense/ts.length:0;const days=month===monthOf()?Number(today().slice(8)):daysInMonth(month),projected=m.expense/days*daysInMonth(month),largest=ts.slice().sort((a,b)=>b.amount-a.amount)[0];return `<section class="stats-grid">${statCard('Net cash flow',m.net,'transactions','Income minus expenses')}${statCard('Savings rate',0,'leaf',m.income?'Share of recorded income retained':'Log income to calculate your rate').replace(money(0,true),m.rate+'%')}${statCard('Average transaction',avg,'bag',ts.length+' expense entries this month')}${statCard('Daily average',m.expense/days,'calendar',days+' calendar days in this period')}</section><div class="analytics-grid"><section class="panel"><div class="panel-head"><div><h2>Your six-month story</h2><p>Income and expenses over time</p></div><div class="legend"><span><i class="income-dot"></i>Income</span><span><i class="expense-dot"></i>Expenses</span></div></div>${cashflowChart()}</section><section class="panel"><div class="panel-head"><div><h2>Spending breakdown</h2><p>Every category, a little clearer</p></div></div>${donut(month)}</section><section class="panel"><div class="panel-head"><div><h2>By category</h2><p>Follow the details, find the patterns</p></div></div>${groups.length?groups.map(c=>`<div class="category-detail"><span class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</span><div><div class="flex-between"><strong>${esc(c.name)}</strong><strong>${money(c.amount)}</strong></div><div class="progress"><i style="background:${c.color};width:${pct(c.amount,m.expense)}%"></i></div></div><span class="muted small">${Math.round(c.amount/m.expense*100)}%</span></div>`).join(''):empty('Patterns take a little time','Your expense categories will appear here.','','','chart')}</section><section class="panel insights-panel"><div class="panel-head"><div><h2>A few things to know</h2><p>Little insights from your recorded activity</p></div>${icon('spark')}</div><div class="insight-item">${icon('chart')}<div><strong>${month===monthOf()?'Your month, at this pace':'Spending for this period'}</strong><p>${month===monthOf()?`At your current daily average, spending would reach ${money(projected,true)} by month end. This is a simple projection, not a forecast.`:`You recorded ${money(m.expense,true)} in expenses across ${ts.length} entries.`}</p></div></div><div class="insight-item">${icon('bag')}<div><strong>${groups[0]?esc(groups[0].name)+' leads the way':'A blank page, full of possibility'}</strong><p>${groups[0]?`${Math.round(groups[0].amount/m.expense*100)}% of your spending went here. Check its budget to see how that fits your plan.`:'Record a few expenses to discover where your money goes.'}</p></div></div><div class="insight-item">${icon('arrow')}<div><strong>Largest expense</strong><p>${largest?`${esc(largest.title)} — ${money(largest.amount)} on ${fmtDate(largest.date)}.`:'No expenses recorded in this month.'}</p></div></div><div class="soft-note">${icon('info')} Analytics use recorded entries through today. Account transfers and goal earmarks are excluded.</div></section></div>`;}
function goals(){const saved=data.goals.reduce((n,g)=>n+g.saved,0);return `<div class="summary-banner"><span class="banner-icon">${icon('goal')}</span><div><span class="muted small">FOR YOUR NEXT CHAPTER</span><h2>${money(saved,true)} <span>earmarked for your dreams</span></h2><p>${data.goals.length} goals · Every small step counts.</p></div></div><div class="goals-grid">${data.goals.map(g=>{const months=Math.max(1,(Number(g.date.slice(0,4))-Number(today().slice(0,4)))*12+Number(g.date.slice(5,7))-Number(today().slice(5,7)));return `<article class="panel goal-card"><div class="flex-between"><span class="large-category-icon" style="--cat:${g.color}">${icon(g.icon)}</span>${button('','edit-goal','dots','icon-button',`data-id="${g.id}" aria-label="Edit ${esc(g.name)}"`)}</div><h2>${esc(g.name)}</h2><p class="muted small">${icon('calendar')} By ${fmtDate(g.date,{month:'long',year:'numeric'})}</p><strong class="goal-amount">${money(g.saved,true)} <span>of ${money(g.target,true)}</span></strong><div class="progress"><i style="background:${g.color};width:${pct(g.saved,g.target)}%"></i></div><div class="flex-between small"><span>${Math.round(pct(g.saved,g.target))}% there</span><span class="muted">${money(Math.max(0,g.target-g.saved),true)} to go</span></div><div class="goal-tip">${icon(g.saved>=g.target?'check':'leaf')}${g.saved>=g.target?'You made it. Take a moment to celebrate.':g.date<today()?'Target date passed — adjust your plan whenever you’re ready.':`About ${money(Math.max(0,g.target-g.saved)/months,true)} a month to reach your goal.`}</div>${button('Add to this goal','fund-goal','plus','button secondary full-width',`data-id="${g.id}"`)}</article>`;}).join('')}<button class="dashed-card" data-action="add-goal">${icon('plus')}<strong>What’s your next someday?</strong><span>Start a new savings goal</span></button></div><div class="soft-note">${icon('info')} Goals earmark money you already have. Adding to a goal does not move money or change account balances. Keep total earmarks within your available savings.</div>`;}
function billRow(r,full=false){const c=r.type==='income'?{icon:'income',color:'#739d79'}:cat(r.category);return `<div class="bill-row"><span class="category-icon" style="--cat:${c.color}">${icon(c.icon)}</span><div class="bill-info"><strong>${esc(r.title)}</strong><small class="${r.next<today()?'negative':'muted'}">${r.next<today()?'Overdue · ':r.next===today()?'Due today · ':''}${fmtDate(r.next)}${full?' · '+r.frequency+' · '+esc(acct(r.account)):''}</small></div><strong class="nowrap ${r.type==='income'?'positive':''}">${r.type==='income'?'+':''}${money(r.amount)}</strong>${full?`<div class="bill-actions">${button('Record','pay-bill','check','button secondary small-button',`data-id="${r.id}"`)}${button('','edit-recurring','dots','icon-button',`data-id="${r.id}" aria-label="Edit ${esc(r.title)}"`)}</div>`:''}</div>`;}
function recurring(){const expense=data.recurring.filter(r=>r.type==='expense').reduce((n,r)=>n+r.amount*(r.frequency==='weekly'?52/12:r.frequency==='yearly'?1/12:1),0),due=data.recurring.filter(r=>r.next<=today()).length;return `<section class="summary-banner"><span class="banner-icon">${icon('repeat')}</span><div><span class="muted small">YOUR REGULAR RHYTHM</span><h2>${money(expense,true)} <span>estimated monthly commitments</span></h2><p>${data.recurring.length} recurring items · ${due} due or overdue</p></div></section><section class="panel"><div class="panel-head"><div><h2>Bills, subscriptions & regular income</h2><p>A little less to keep in your head</p></div></div>${data.recurring.length?data.recurring.slice().sort((a,b)=>a.next.localeCompare(b.next)).map(r=>billRow(r,true)).join(''):empty('Keep the regular things together','Add rent, subscriptions, bills, or recurring income.','add-recurring','Add a recurring item','repeat')}</section><div class="soft-note">${icon('info')} Recurring items are reminders. “Record” adds one transaction today and moves the due date forward by one interval. Nothing is charged or logged automatically. Weekly estimates use 52 ÷ 12.</div>`;}
function settings(){return `<div class="settings-grid"><section class="panel settings-panel"><div class="panel-head"><div><h2>Your space, your way</h2><p>The little details that make it yours</p></div>${icon('settings')}</div><form id="preferences-form">${field('Display name','name',data.name,'text','required maxlength="40"')}${select('Currency (labels only; amounts are not converted)','currency',options(currencies.map(c=>[c,c]),data.currency))}${select('Appearance','theme',themeOptions())}${select('Color theme','colorTheme',colorOptions())}${select('Auto-lock after inactivity','lockMinutes',options([['5','5 minutes'],['15','15 minutes'],['30','30 minutes']],String(data.preferences.lockMinutes)))}<label class="toggle-row"><span><strong>A little haptic feedback</strong><small>Gentle vibration after saving, on supported phones</small></span><input name="haptics" type="checkbox" ${data.preferences.haptics?'checked':''} role="switch"></label><p id="preferences-error" class="form-error" role="alert" hidden></p><button class="button primary" type="submit">${icon('check')}Save preferences</button></form></section><div class="settings-stack"><section class="panel settings-panel"><div class="panel-head"><div><h2>Back up your peace of mind</h2><p>Keep a copy. Keep your password.</p></div>${icon('shield')}</div><p class="muted">Your data lives only in this browser, encrypted with your password. Clearing browser data removes it. Export a backup regularly.</p><div class="settings-actions">${button('Encrypted backup','backup','download','button primary')}${button('Restore backup','restore','upload')}${button('Export all CSV','export-all-csv','download')}</div><p class="small muted">Backups include receipts, accounts, budgets and goals. CSV contains readable transactions only. Restoring creates a separate profile and keeps existing profiles.</p></section><section class="panel settings-panel"><div class="panel-head"><div><h2>Privacy & security</h2><p>Your data stays in your hands</p></div>${icon('lock')}</div><div class="privacy-fact">${icon('check')} AES-256-GCM encryption at rest</div><div class="privacy-fact">${icon('check')} Password key stays in memory while unlocked</div><div class="privacy-fact">${icon('check')} No analytics, trackers, or bank credentials</div><p class="small muted">Usernames are visible in this browser’s profile list. There is no password reset or cross-device sync. Anyone with your password and backup can open that backup.</p><div class="settings-actions">${button('Change password','change-password','lock','button secondary',demo?'disabled':'')}${button(demo?'Exit demo':'Lock now','lock','logout')}</div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>Take a little clarity with you</h2><p>Built for your everyday, on any screen</p></div>${icon('globe')}</div><p class="muted">Install MayaXpense on your home screen. Capture receipt photos, use quick-add, and swipe left or right on page headings to change months.</p>${button('Install / mobile tips','install','plus')}</section></div><section class="panel settings-panel categories-panel"><div class="panel-head"><div><h2>Make your own categories</h2><p>Organize spending in a way that feels like you</p></div>${button('Add category','add-category','plus')}</div><div class="category-chips">${data.categories.map(c=>`<button data-action="edit-category" data-id="${c.id}" class="category-chip"><span style="color:${c.color}">${icon(c.icon)}</span>${esc(c.name)}${icon('edit')}</button>`).join('')}</div></section></div>`;}

function transactionModal(id='',initialType='expense'){const t=data.transactions.find(t=>t.id===id);receiptDraft=t?.receipt||'';const type=t?.type||initialType;openModal(t?'The little details':'Add a little detail',t?'Update this transaction or remove it.':'Every entry helps the bigger picture.',`<form id="transaction-form" data-id="${id}"><div class="segmented transaction-types">${['expense','income','transfer'].map(v=>`<label class="${type===v?'selected':''}"><input type="radio" name="type" value="${v}" ${type===v?'checked':''}>${icon(v==='expense'?'arrow':v==='income'?'income':'transactions')}${v[0].toUpperCase()+v.slice(1)}</label>`).join('')}</div><div class="amount-entry"><label for="amount">Amount <span>${data.currency}</span></label><input id="amount" name="amount" type="number" inputmode="decimal" min="0.01" step="0.01" max="10000000000" required value="${t?(t.amount/100).toFixed(2):''}" placeholder="0.00" autofocus></div>${field('Description','title',t?.title||'','text','required maxlength="120" placeholder="Coffee, groceries, something good…"')}<div class="form-grid">${field('Date','date',t?.date||today(),'date','required min="1900-01-01" max="2200-12-31"')}${select('Account','account',accountOptions(t?.account||data.accounts[0].id))}<div id="category-field" ${type!=='expense'?'hidden':''}>${select('Category','category',categoryOptions(t?.category))}</div><div id="to-field" ${type!=='transfer'?'hidden':''}>${select('To account','to',accountOptions(t?.to||data.accounts[1]?.id))}</div>${field('Tags (comma separated)','tags',t?.tags?.join(', ')||'','text','maxlength="300" placeholder="personal, weekend…"')}</div><label class="field">A note, if you like<textarea name="note" maxlength="2000" rows="2" placeholder="A little context for future you">${esc(t?.note||'')}</textarea></label><div class="receipt-section"><label class="receipt-upload">${icon('camera')}<span>Attach / photograph a receipt<small>Camera on supported mobile devices · Stored encrypted</small></span><input id="receipt-input" type="file" accept="image/jpeg,image/png,image/webp" capture="environment"></label><div id="receipt-preview">${receiptMarkup()}</div></div>${t?`<div class="form-delete">${button('Delete transaction','delete-transaction','trash','text-button danger',`data-id="${t.id}"`)}</div>`:''}${formEnd(t?'Save transaction':'Add transaction')}</form>`);}
function receiptMarkup(){return receiptDraft?`<div class="receipt-thumb"><img src="${receiptDraft}" alt="Attached receipt">${button('Remove receipt','remove-receipt','close','text-button')}</div>`:'';}
function budgetModal(id=''){const b=data.budgets.find(b=>b.id===id);openModal(b?'Fine-tune your plan':'Give your money a plan',`A category budget for ${monthName(month)}.`,`<form id="budget-form" data-id="${id}">${select('Category','category',categoryOptions(b?.category))}${field('Monthly limit ('+data.currency+')','limit',b?b.limit/100:'','number','required min="0.01" max="10000000000" step="0.01" inputmode="decimal" placeholder="e.g. 8000"')}<p class="small muted">We’ll show your spending against this limit. You can adjust it anytime.</p>${b?`<div class="form-delete">${button('Remove budget','delete-budget','trash','text-button danger',`data-id="${id}"`)}</div>`:''}${formEnd(b?'Save budget':'Create budget')}</form>`);}
function accountModal(id=''){const a=data.accounts.find(a=>a.id===id);openModal(a?'Your account details':'One more piece of the picture','Track an account manually. No bank login needed.',`<form id="account-form" data-id="${id}">${field('Account name','name',a?.name||'','text','required maxlength="80" placeholder="e.g. Everyday account"')}${select('Account type','type',options([['bank','Bank account'],['cash','Cash wallet'],['savings','Savings'],['credit','Credit card / loan'],['investment','Investments (manual value)']],a?.type||'bank'))}${field('Opening balance ('+data.currency+')','opening',a?a.opening/100:'0','number','required step="0.01" min="-10000000000" max="10000000000" inputmode="decimal"')}<p class="small muted">The balance before your recorded transactions. Use a negative amount for money you owe. Editing this changes your current balance.</p>${field('Account color','color',a?.color||'#244c3e','color')}${a?`<div class="form-delete">${button('Delete empty account','delete-account','trash','text-button danger',`data-id="${id}"`)}</div>`:''}${formEnd(a?'Save account':'Add account')}</form>`);}
function goalModal(id=''){const g=data.goals.find(g=>g.id===id);openModal(g?'A little change of plan':'What are you dreaming of?','Give your next chapter a name and a little momentum.',`<form id="goal-form" data-id="${id}">${field('Goal name','name',g?.name||'','text','required maxlength="80" placeholder="e.g. My next adventure"')}<div class="form-grid">${field('Target amount ('+data.currency+')','target',g?g.target/100:'','number','required min="0.01" max="10000000000" step="0.01" inputmode="decimal"')}${field('Already earmarked','saved',g?g.saved/100:0,'number','required min="0" max="10000000000" step="0.01" inputmode="decimal"')}${field('Target date','date',g?.date||shiftMonth(monthOf(),6)+'-01','date','required min="1900-01-01" max="2200-12-31"')}${select('Icon','icon',options([['plane','Travel & adventure'],['shield','Emergency fund'],['home','A place to call home'],['briefcase','Work & equipment'],['heart','Health & wellbeing'],['book','Learning'],['goal','Something else']],g?.icon||'goal'))}</div>${field('Goal color','color',g?.color||'#739d79','color')}<p class="small muted">This is an earmark, not a bank transfer. Account balances stay the same.</p>${g?`<div class="form-delete">${button('Remove goal','delete-goal','trash','text-button danger',`data-id="${id}"`)}</div>`:''}${formEnd(g?'Save goal':'Create goal')}</form>`);}
function fundGoalModal(id){const g=data.goals.find(g=>g.id===id);openModal('A little closer to '+esc(g.name),`${money(g.saved,true)} earmarked of ${money(g.target,true)}.`,`<form id="fund-form" data-id="${id}">${field('Add amount ('+data.currency+')','amount','','number','required min="-10000000000" max="10000000000" step="0.01" inputmode="decimal" placeholder="e.g. 2000"')}<p class="small muted">Use a negative amount to reduce an earmark. This does not move money between accounts.</p>${formEnd('Update earmark')}</form>`);}
function recurringModal(id=''){const r=data.recurring.find(r=>r.id===id);openModal(r?'Keep your rhythm up to date':'One less thing to remember','Track a regular bill, subscription, or income.',`<form id="recurring-form" data-id="${id}">${field('Description','title',r?.title||'','text','required maxlength="120" placeholder="e.g. Rent, salary, Spotify"')}<div class="form-grid">${select('Type','type',options([['expense','Expense'],['income','Income']],r?.type||'expense'))}${field('Amount ('+data.currency+')','amount',r?r.amount/100:'','number','required min="0.01" max="10000000000" step="0.01" inputmode="decimal"')}${select('Frequency','frequency',options([['monthly','Monthly'],['weekly','Weekly'],['yearly','Yearly']],r?.frequency||'monthly'))}${field('Next due date','next',r?.next||today(),'date','required min="1900-01-01" max="2200-12-31"')}${select('Account','account',accountOptions(r?.account))}${select('Category (expenses only)','category',categoryOptions(r?.category))}</div><p class="small muted">A reminder only. You choose when to record each occurrence.</p>${r?`<div class="form-delete">${button('Remove recurring item','delete-recurring','trash','text-button danger',`data-id="${id}"`)}</div>`:''}${formEnd(r?'Save recurring item':'Add recurring item')}</form>`);}
function categoryModal(id=''){const c=data.categories.find(c=>c.id===id);openModal(c?'A category, your way':'Make room for a new category','Something that makes sense for how you spend.',`<form id="category-form" data-id="${id}">${field('Category name','name',c?.name||'','text','required maxlength="80"')}${select('Icon','icon',options([['food','Food & drinks'],['bag','Shopping'],['home','Home'],['car','Transport'],['heart','Health'],['play','Entertainment'],['bolt','Bills'],['plane','Travel'],['book','Education'],['coffee','Coffee'],['briefcase','Work'],['dots','Other']],c?.icon||'dots'))}${field('Category color','color',c?.color||palette[data.categories.length%8],'color')}${c?`<div class="form-delete">${button('Delete unused category','delete-category','trash','text-button danger',`data-id="${id}"`)}</div>`:''}${formEnd(c?'Save category':'Add category')}</form>`);}
function restoreModal(){openModal('Bring your money story with you','Restore an encrypted backup as a new local profile.',`<form id="restore-form"><label class="field">Encrypted backup file<input type="file" name="backup" accept=".json,application/json" required></label>${field('Password used when this backup was exported','password','','password','required maxlength="200" autocomplete="off"')}${field('Username for the restored profile','username','','text','required minlength="3" maxlength="24" placeholder="e.g. alex-restored"')}<p class="small muted">Existing profiles remain unchanged. The restored profile keeps the backup’s password. There is no password recovery.</p>${formEnd('Restore profile')}</form>`);}
function csvModal(){openModal('Bring in the little details','Import transaction records from a CSV file.',`<form id="csv-form"><label class="field">CSV file<input name="csv" type="file" accept=".csv,text/csv" required></label><p class="small muted">Required columns: <b>date, type, title, amount, account</b>. For expenses, include <b>category</b>; transfers require <b>to</b>. Dates use YYYY-MM-DD. Amounts are positive, in ${data.currency}. Account and category names must match your existing ones.</p><p class="small muted">Optional: note, tags (semicolon separated). Exact duplicate entries are skipped. Import up to 5,000 rows. A file with invalid rows is rejected in full.</p>${button('Download example CSV','csv-template','download')}${formEnd('Import transactions')}</form>`);}
function alertsModal(){const alerts=[...limitsFor(data,month).filter(b=>categorySpent(data,month,b.category)>=b.limit*.8).map(b=>({icon:'budget',title:cat(b.category).name,text:`${money(categorySpent(data,month,b.category),true)} of ${money(b.limit,true)} used in ${monthName(month)}.`})),...data.recurring.filter(r=>r.next<=today()).map(r=>({icon:'calendar',title:r.title,text:`${r.next<today()?'Overdue since':'Due'} ${fmtDate(r.next)} · ${money(r.amount)}. Record it in Recurring.`}))];openModal('A little heads-up','Your budgets and bills, all caught up.',alerts.length?`<div class="alert-list">${alerts.map(a=>`<div class="insight-item">${icon(a.icon)}<div><strong>${esc(a.title)}</strong><p>${esc(a.text)}</p></div></div>`).join('')}</div>`:empty('You’re all caught up','No budget warnings or bills due today.','','','check'));}
function download(content,name,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportCSV(all=false){const ts=all?data.transactions:filteredTransactions();download(toCSV([['date','type','title','amount','account','category','to','note','tags'],...ts.map(t=>[t.date,t.type,t.title,(t.amount/100).toFixed(2),acct(t.account),t.type==='expense'?cat(t.category).name:'',t.to?acct(t.to):'',t.note||'',(t.tags||[]).join(';')])]),`MayaXpense-transactions-${all?'all':month}.csv`,'text/csv;charset=utf-8');toast('CSV exported. It contains readable financial records.');}
async function backup(){const env=demo?await seal(data,await deriveKey('mayaxpense-demo',DEMO_SALT),DEMO_SALT):await seal(data,session.key,session.salt,session.revision);download(JSON.stringify(env),`MayaXpense-backup-${today()}.json`);toast(demo?'Demo backup exported. Password: mayaxpense-demo':'Encrypted backup exported. Keep it with your password.');}
const DEMO_SALT='bWF5YXhwZW5zZS1kZW1vIQ==';
function go(nav){page=nav;search='';filterType='';filterAccount='';filterCategory='';pageNum=1;render();window.scrollTo({top:0});}
async function logout(){if(saveBusy){toast('Please wait until saving finishes.');return;}closeModal();data=null;session=null;demo=false;undo=null;page='overview';search='';render();}

const actions={
 'auth-login':()=>{authMode='login';renderAuth();},'auth-signup':()=>{authMode='signup';renderAuth();},
 'show-password':e=>{const input=e.closest('.password-field').querySelector('input');input.type=input.type==='password'?'text':'password';e.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password');},
 'demo':()=>{data=demoData();demo=true;session=null;page='overview';lastActivity=Date.now();render();},'close':closeModal,'lock':logout,
 'theme':()=>openModal('Make yourself at home','Choose a look. Changes apply immediately on this device.',`<div class="appearance-options">${select('Appearance','theme',themeOptions())}${select('Color theme','colorTheme',colorOptions())}<div class="appearance-preview"><span>${icon('leaf')} Your space, your way</span><strong>A little more clarity.</strong></div><p class="small muted">Your choice is shared by the sign-in screen and your workspace.</p><div class="modal-footer">${button('Done','close','','button primary')}</div></div>`),
 'add-transaction':()=>transactionModal(),'edit-transaction':e=>transactionModal(e.dataset.id),'transfer':()=>transactionModal('','transfer'),
 'add-budget':()=>budgetModal(),'edit-budget':e=>budgetModal(e.dataset.id),'add-account':()=>accountModal(),'edit-account':e=>accountModal(e.dataset.id),
 'add-goal':()=>goalModal(),'edit-goal':e=>goalModal(e.dataset.id),'fund-goal':e=>fundGoalModal(e.dataset.id),
 'add-recurring':()=>recurringModal(),'edit-recurring':e=>recurringModal(e.dataset.id),'add-category':()=>categoryModal(),'edit-category':e=>categoryModal(e.dataset.id),
 'goto-budgets':()=>go('budgets'),'goto-analytics':()=>go('analytics'),
 'prev-month':()=>{month=shiftMonth(month,-1);pageNum=1;render();},'next-month':()=>{month=shiftMonth(month,1);pageNum=1;render();},
 'prev-page':()=>{pageNum--;render();},'next-page':()=>{pageNum++;render();},'alerts':alertsModal,
 'backup':backup,'restore':restoreModal,'export-csv':()=>exportCSV(),'export-all-csv':()=>exportCSV(true),'import-csv':csvModal,
 'export-report':()=>{const s=summary(data,month);download(toCSV([['MayaXpense monthly report',month],['Currency',data.currency],['Includes records through',today()],[],['Metric','Amount'],['Income',(s.income/100).toFixed(2)],['Expenses',(s.expense/100).toFixed(2)],['Net cash flow',(s.net/100).toFixed(2)],['Savings rate',s.rate+'%'],[],['Category','Spent','Budget'],...breakdown(data,month).map(c=>[c.name,(c.amount/100).toFixed(2),(limitsFor(data,month).find(b=>b.category===c.id)?.limit/100||0).toFixed(2)])]),`MayaXpense-report-${month}.csv`,'text/csv;charset=utf-8');toast('Monthly report exported.');},
 'remove-receipt':()=>{receiptDraft='';$('#receipt-preview').innerHTML='';},
 'csv-template':()=>download(toCSV([['date','type','title','amount','account','category','to','note','tags'],[today(),'expense','Example groceries','250.00',data.accounts[0].name,data.categories[0].name,'','An example — replace this row','personal']]),'MayaXpense-example.csv','text/csv'),
 'copy-budgets':async()=>{const prev=limitsFor(data,shiftMonth(month,-1));if(!prev.length)throw Error('There are no budgets in the previous month to copy.');await commit(d=>{for(const b of prev)if(!d.budgets.some(x=>x.month===month&&x.category===b.category))d.budgets.push({...b,id:uid(),month});},'Missing category budgets copied from last month.',true);},
 'pay-bill':e=>{const r=data.recurring.find(r=>r.id===e.dataset.id);openModal('Record '+esc(r.title)+'?',`${money(r.amount)} · ${esc(acct(r.account))}`,`<form id="pay-form" data-id="${r.id}"><p class="muted">This adds one ${r.type} today and advances the due date from ${fmtDate(r.next)} to ${fmtDate(advanceDate(r.next,r.frequency,r.anchor))}. ${r.next>today()?'You’re recording this ahead of its due date.':''}</p>${formEnd('Record transaction')}</form>`);},
 'undo':async()=>{if(!undo)return;const old=undo;await commit(d=>{for(const k of Object.keys(d))delete d[k];Object.assign(d,old);},'Change undone.');},
 'change-password':()=>{if(demo)return;openModal('A new key to your space','Existing backup files keep their original password.',`<form id="password-form">${field('Current password','current','','password','required autocomplete="current-password"')}${field('New password (10+ characters)','password','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}${field('Confirm new password','confirm','','password','required minlength="10" maxlength="200" autocomplete="new-password"')}<p class="small muted">After changing it, export a new backup. There is no password reset.</p>${formEnd('Change password')}</form>`);},
 'install':async()=>{if(installPrompt){await installPrompt.prompt();const result=await installPrompt.userChoice;installPrompt=null;toast(result.outcome==='accepted'?'MayaXpense is ready for your home screen.':'You can install later from your browser menu.');return;}openModal('A little clarity, on the go','Your everyday money companion.',`<div class="install-tips"><div class="insight-item">${icon('plus')}<div><strong>Add to your home screen</strong><p>On iPhone: Safari → Share → Add to Home Screen. On Android or desktop: your browser menu → Install app / Add to Home Screen. Availability depends on your browser.</p></div></div><div class="insight-item">${icon('camera')}<div><strong>Snap a receipt</strong><p>Open Add transaction and tap the receipt attachment. Supported mobile browsers offer the camera. Photos are compressed and encrypted with your records.</p></div></div><div class="insight-item">${icon('transactions')}<div><strong>A little swipe, a different month</strong><p>Swipe the page heading left for next month, right for last month. Use your keyboard: N to add, / to search, Escape to close a dialog.</p></div></div><div class="insight-item">${icon('lock')}<div><strong>Ready when the connection isn’t</strong><p>After the first online load, the app shell works offline on supported browsers. Export backups often; data stays on this device.</p></div></div></div>`);},
 'more':()=>openModal('Your workspace','Everything you need, a tap away.',`<div class="mobile-more">${[...navs,['settings','settings','Settings & backup']].map(([key,ico,label])=>`<button data-nav="${key}">${icon(ico)}${label}${icon('chevron')}</button>`).join('')}${button(demo?'Exit demo':'Lock and sign out','lock','logout')}</div>`)
};
for(const [kind,key] of [['transaction','transactions'],['budget','budgets'],['goal','goals'],['recurring','recurring'],['account','accounts'],['category','categories']])actions['delete-'+kind]=async e=>{const id=e.dataset.id;if(key==='accounts'){if(data.accounts.length===1)throw Error('Keep at least one account.');if(data.transactions.some(t=>t.account===id||t.to===id)||data.recurring.some(r=>r.account===id))throw Error('This account has transactions or recurring items. Move or remove those first.');}if(key==='categories'){if(data.categories.length===1)throw Error('Keep at least one category.');if(data.transactions.some(t=>t.category===id)||data.recurring.some(r=>r.category===id)||data.budgets.some(b=>b.category===id))throw Error('This category is in use. Update its transactions, budgets, and recurring items first.');}await commit(d=>{d[key]=d[key].filter(x=>x.id!==id);},`${kind[0].toUpperCase()+kind.slice(1)} removed.`,true);closeModal();};

document.addEventListener('click',async e=>{const nav=e.target.closest('[data-nav]');if(nav&&data){e.preventDefault();closeModal();go(nav.dataset.nav);return;}const target=e.target.closest('[data-action]');if(!target)return;e.preventDefault();try{await actions[target.dataset.action]?.(target);}catch(error){showError(friendlyError(error));}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,fd=new FormData(form),v=Object.fromEntries(fd),id=form.dataset.id,submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;try{
 if(form.id==='auth-form'){if(!crypto.subtle)throw Error('Encryption requires HTTPS or localhost. Open this app on its secure Vercel URL.');if(authMode==='signup'){if(v.password!==v.confirm)throw Error('Passwords don’t match.');const next=freshData(v.name.trim());if(!next.name)throw Error('Enter your name.');session=await createProfile(v.username.trim(),v.password,next);data=next;}else {const result=await unlock(v.username.trim(),v.password);validateData(result.data);data=result.data;session=result.session;}demo=false;page='overview';lastActivity=Date.now();render();if(new URLSearchParams(location.search).get('action')==='add')transactionModal();return;}
 if(form.id==='restore-form'){const file=fd.get('backup');if(file.size>16000000)throw Error('Backup must be under 16 MB.');const env=checkEnvelope(JSON.parse(await file.text()));const key=await deriveKey(v.password,env.salt);let restored;try{restored=validateData(await unseal(env,key));}catch{throw Error('Cannot open this backup. Check its password and file.');}const restoredSession=await createProfile(v.username.trim(),v.password,restored);data=restored;session=restoredSession;demo=false;page='overview';lastActivity=Date.now();closeModal();render();toast('Backup restored as a new profile.');return;}
 if(form.id==='transaction-form'){if(receiptBusy)throw Error('Your receipt is still being prepared. Try again in a moment.');const t={id:id||uid(),type:v.type,amount:cents(v.amount),title:v.title.trim(),date:v.date,account:v.account,category:v.type==='expense'?v.category:'',to:v.type==='transfer'?v.to:'',note:v.note.trim(),tags:v.tags.split(',').map(s=>s.trim()).filter(Boolean),...(receiptDraft?{receipt:receiptDraft}:{})};validateTransaction(t,data);await commit(d=>{if(id)d.transactions[d.transactions.findIndex(t=>t.id===id)]=t;else d.transactions.push(t);},id?'Transaction updated.':'A little detail, saved.');closeModal();return;}
 if(form.id==='budget-form'){const limit=cents(v.limit);if(limit<=0)throw Error('Enter a positive monthly limit.');if(data.budgets.some(b=>b.id!==id&&b.month===month&&b.category===v.category))throw Error('This category already has a budget for this month. Edit that budget instead.');await commit(d=>{const b={id:id||uid(),month,category:v.category,limit};if(id)d.budgets[d.budgets.findIndex(x=>x.id===id)]=b;else d.budgets.push(b);},'A little plan, saved.');closeModal();return;}
 if(form.id==='account-form'){if(!v.name.trim())throw Error('Give this account a name.');if(data.accounts.some(a=>a.id!==id&&a.name.toLowerCase()===v.name.trim().toLowerCase()))throw Error('Use a different account name.');await commit(d=>{const a={id:id||uid(),name:v.name.trim(),type:v.type,opening:cents(v.opening),color:v.color};if(id)d.accounts[d.accounts.findIndex(x=>x.id===id)]=a;else d.accounts.push(a);},'Account saved.');closeModal();return;}
 if(form.id==='goal-form'){const g={id:id||uid(),name:v.name.trim(),target:cents(v.target),saved:cents(v.saved),date:v.date,color:v.color,icon:v.icon};if(!g.name||g.target<=0||g.saved<0||!validDate(g.date))throw Error('Add a name, positive target, valid date, and a non-negative earmark.');await commit(d=>{if(id)d.goals[d.goals.findIndex(x=>x.id===id)]=g;else d.goals.push(g);},'Your someday has a plan.');closeModal();return;}
 if(form.id==='fund-form'){const amount=cents(v.amount);if(!amount)throw Error('Enter an amount to add or subtract.');if(data.goals.find(g=>g.id===id).saved+amount<0)throw Error('An earmark can’t be less than zero.');await commit(d=>{d.goals.find(g=>g.id===id).saved+=amount;},'Goal earmark updated.');closeModal();return;}
 if(form.id==='recurring-form'){const r={id:id||uid(),type:v.type,title:v.title.trim(),amount:cents(v.amount),account:v.account,category:v.type==='expense'?v.category:'',next:v.next,frequency:v.frequency,anchor:Number(v.next.slice(8)),note:'',tags:[]};validateTransaction({...r,date:r.next},data);await commit(d=>{if(id)d.recurring[d.recurring.findIndex(x=>x.id===id)]=r;else d.recurring.push(r);},'Recurring item saved.');closeModal();return;}
 if(form.id==='pay-form'){const r=data.recurring.find(r=>r.id===id);await commit(d=>{d.transactions.push({id:uid(),type:r.type,title:r.title,amount:r.amount,category:r.category,account:r.account,date:today(),note:`Recurring ${r.frequency} item. Due ${r.next}.`,tags:['recurring']});d.recurring.find(x=>x.id===id).next=advanceDate(r.next,r.frequency,r.anchor);},'Recorded. Your next due date is ready.',true);closeModal();return;}
 if(form.id==='category-form'){if(!v.name.trim())throw Error('Give this category a name.');if(data.categories.some(c=>c.id!==id&&c.name.toLowerCase()===v.name.trim().toLowerCase()))throw Error('That category name already exists.');await commit(d=>{const c={id:id||uid(),name:v.name.trim(),icon:v.icon,color:v.color};if(id)d.categories[d.categories.findIndex(x=>x.id===id)]=c;else d.categories.push(c);},'Category saved.');closeModal();return;}
 if(form.id==='preferences-form'){const prefsTheme=v.theme,prefsColor=v.colorTheme;await commit(d=>{d.name=v.name.trim();if(!d.name)throw Error('Enter a display name.');d.currency=v.currency;d.preferences={lockMinutes:Number(v.lockMinutes),haptics:fd.has('haptics')};},'Your space, updated.');setAppearance(prefsTheme,prefsColor);applyTheme();render();return;}
 if(form.id==='password-form'){if(v.password!==v.confirm)throw Error('New passwords don’t match.');if(v.password.length<10)throw Error('Use at least 10 characters.');if(saveBusy)throw Error('Wait for the current save.');const operation=async()=>{const current=JSON.parse(localStorage.getItem(vaultKey(session.id)));if(current.revision!==session.revision)throw Error('Your vault changed in another tab. Lock and sign in again.');const oldKey=await deriveKey(v.current,session.salt);try{await unseal(current,oldKey);}catch{throw Error('Your current password is incorrect.');}const salt=newSalt(),key=await deriveKey(v.password,salt),env=await seal(data,key,salt,session.revision+1);if(JSON.parse(localStorage.getItem(vaultKey(session.id))).revision!==session.revision)throw Error('Your vault changed in another tab. Lock and sign in again.');localStorage.setItem(vaultKey(session.id),JSON.stringify(env));session={...session,salt,key,revision:env.revision};};saveBusy=true;try{if(navigator.locks)await navigator.locks.request('mayaxpense-'+session.id,operation);else await operation();}finally{saveBusy=false;}closeModal();toast('Password changed. Export a new encrypted backup.');return;}
 if(form.id==='csv-form'){const file=fd.get('csv');if(file.size>5000000)throw Error('CSV must be under 5 MB.');const rows=parseCSV((await file.text()).replace(/^\uFEFF/,''));if(rows.length<2)throw Error('Include a header and at least one transaction.');const headers=rows.shift().map(s=>s.trim().toLowerCase());for(const h of ['date','type','title','amount','account'])if(!headers.includes(h))throw Error('Missing CSV column: '+h);const records=rows.map((row,i)=>{const r=Object.fromEntries(headers.map((h,j)=>[h,(row[j]||'').replace(/^'(?=[=+@\-\t\r])/,'').trim()]));const a=data.accounts.find(a=>a.name.toLowerCase()===r.account.toLowerCase()),c=data.categories.find(c=>c.name.toLowerCase()===(r.category||'').toLowerCase()),to=data.accounts.find(a=>a.name.toLowerCase()===(r.to||'').toLowerCase());const t={id:uid(),date:r.date,type:r.type.toLowerCase(),title:r.title,amount:cents(r.amount),account:a?.id||'',category:c?.id||'',to:to?.id||'',note:r.note||'',tags:(r.tags||'').split(';').filter(Boolean)};try{validateTransaction(t,data);}catch(error){throw Error(`Row ${i+2}: ${error.message}`);}return t;});const signature=t=>[t.date,t.type,t.title,t.amount,t.account,t.to||'',t.category||''].join('|');const seen=new Set(data.transactions.map(signature)),unique=records.filter(t=>{const sig=signature(t);if(seen.has(sig))return false;seen.add(sig);return true;});if(!unique.length)throw Error('All rows already exist. Nothing to import.');await commit(d=>d.transactions.push(...unique),`${unique.length} transactions imported. ${records.length-unique.length} duplicates skipped.`,true);closeModal();return;}
 }catch(error){if(form.id==='preferences-form'){const err=$('#preferences-error');err.hidden=false;err.textContent=friendlyError(error);}else showError(friendlyError(error));}finally{if(submit?.isConnected)submit.disabled=false;}});

document.addEventListener('change',async e=>{const el=e.target;if(el.closest('.appearance-options')&&['theme','colorTheme'].includes(el.name)){setAppearance(el.name==='theme'?el.value:appearance.theme,el.name==='colorTheme'?el.value:appearance.color);applyTheme();}if(el.name==='type'&&el.closest('#transaction-form')){$('#category-field').hidden=el.value!=='expense';$('#to-field').hidden=el.value!=='transfer';el.closest('.transaction-types').querySelectorAll('label').forEach(l=>l.classList.toggle('selected',l.querySelector('input').checked));}if(el.type==='month'){if(/^\d{4}-(0[1-9]|1[0-2])$/.test(el.value)&&el.value>='1900-01'&&el.value<='2200-12'){month=el.value;pageNum=1;render();}}if(['filter-type','filter-category','filter-account','sort'].includes(el.id)){if(el.id==='filter-type')filterType=el.value;if(el.id==='filter-category')filterCategory=el.value;if(el.id==='filter-account')filterAccount=el.value;if(el.id==='sort')sort=el.value;pageNum=1;$('#page-content').innerHTML=transactions();}if(el.id==='receipt-input'&&el.files[0]){receiptBusy=true;try{const file=el.files[0];if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>12000000)throw Error('Choose a JPG, PNG, or WebP image under 12 MB.');const url=URL.createObjectURL(file),img=new Image();try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=()=>reject(Error('Could not read this image.'));img.src=url;});const scale=Math.min(1,1000/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);const encoded=canvas.toDataURL('image/jpeg',.65);if(encoded.length>450000)throw Error('This image is still too large. Crop or resize it first.');if($('#receipt-preview')){receiptDraft=encoded;$('#receipt-preview').innerHTML=receiptMarkup();}}finally{URL.revokeObjectURL(url);}}catch(error){showError(friendlyError(error));}finally{receiptBusy=false;}}});
document.addEventListener('input',e=>{if(e.target.id==='transaction-search'){const start=e.target.selectionStart;search=e.target.value;pageNum=1;$('#page-content').innerHTML=transactions();const next=$('#transaction-search');next.focus();next.setSelectionRange(start,start);}});
document.addEventListener('keydown',e=>{lastActivity=Date.now();if(!data||e.ctrlKey||e.metaKey||e.altKey||modalRoot.firstElementChild||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(e.key.toLowerCase()==='n'){e.preventDefault();transactionModal();}if(e.key==='/'){e.preventDefault();go('transactions');$('#transaction-search')?.focus();}});
for(const event of ['pointerdown','touchstart','scroll'])document.addEventListener(event,()=>{lastActivity=Date.now();},{passive:true});
setInterval(()=>{if(data&&!demo&&!saveBusy&&Date.now()-lastActivity>data.preferences.lockMinutes*60000){logout();toast('Your space was locked after inactivity.');}},15000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&data&&!demo&&Date.now()-lastActivity>data.preferences.lockMinutes*60000)logout();});
window.addEventListener('storage',e=>{if(session&&e.key===vaultKey(session.id)&&!saveBusy){logout();toast('Your vault changed in another tab. Sign in to load the latest version.');}});
let swipeStart=null;document.addEventListener('touchstart',e=>{if(e.target.closest('.page-heading')&&!e.target.closest('input,button'))swipeStart=[e.changedTouches[0].clientX,e.changedTouches[0].clientY];},{passive:true});document.addEventListener('touchend',e=>{if(!swipeStart)return;const dx=e.changedTouches[0].clientX-swipeStart[0],dy=e.changedTouches[0].clientY-swipeStart[1];swipeStart=null;if(Math.abs(dx)>75&&Math.abs(dy)<45&&['overview','transactions','budgets','analytics'].includes(page)){month=shiftMonth(month,dx<0?1:-1);pageNum=1;haptic();render();}},{passive:true});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
render();
